const topicLabels={"Fondamenti di backend, HTTP, REST ed Express": "Backend-Grundlagen, HTTP, REST und Express", "Autenticazione e sicurezza delle password": "Authentifizierung und Passwortsicherheit", "Gestione degli errori in Express": "Fehlerbehandlung in Express", "Database relazionali e SQL": "Relationale Datenbanken und SQL", "Docker, container e Docker Compose": "Docker, Container und Docker Compose", "Accesso ai dati, repository e connection pool": "Datenzugriff, Repository und Connection Pool", "Next.js: App Router, pagine, componenti e navigazione": "Next.js: App Router, Seiten, Komponenten und Navigation", "Next.js: Loading e Error Boundaries": "Next.js: Loading und Error Boundaries", "Prisma, Neon, migrazioni e seeding": "Prisma, Neon, Migrationen und Seeding", "Monorepo e integrazione frontend/backend": "Monorepo und Frontend-/Backend-Integration"};
const topicLabel=t=>topicLabels[t]||t;
const app=document.querySelector('#app'),KEY='backend-lab-v1';
let bank=[],state={attempts:[],session:null,last:[]},storageOK=true;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
try{const s=JSON.parse(localStorage.getItem(KEY));if(s&&Array.isArray(s.attempts)&&Array.isArray(s.last))state=s;}catch{storageOK=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;}}
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){let r=new Uint32Array(1);crypto.getRandomValues(r);const j=Math.floor(r[0]/4294967296*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
const topics=()=>[...new Set(bank.map(q=>q.thema))];
const stat=(label,value,sub,cls='')=>`<div class="stat ${cls}"><label>${label}</label><strong>${value}</strong><small>${sub}</small></div>`;
function notice(){return storageOK?'':'<p class="notice" role="alert">Dein Browser kann den Fortschritt nicht speichern. Lass diese Seite geöffnet, um ihn während der Sitzung zu behalten.</p>';}
function home(){const a=state.attempts,correct=a.filter(x=>x.correct).length,seen=new Set(a.map(x=>x.qid)).size,pct=Math.round(seen/bank.length*100);
app.innerHTML=`${notice()}<div class="intro"><div><div class="eyebrow">Dein Raum für die Prüfungsvorbereitung</div><h1>Lerne. Teste dein Wissen.</h1><p>Vertiefe dein Backend-Wissen – ein Thema nach dem anderen.</p></div><span class="badge">${bank.length} Fragen &nbsp;·&nbsp; ${topics().length} Themen</span></div><div class="stats">${stat('Antworten insgesamt',a.length,'Alle bisherigen Antwortversuche')}${stat('Richtige Antworten',correct,a.length?Math.round(correct/a.length*100)+'% richtig':'Dein nächstes Ziel','correct')}${stat('Falsche Antworten',a.length-correct,'Aus jedem Fehler lernen','wrong')}${stat('Einmalig bearbeitete Fragen',seen+' <small>/ '+bank.length+'</small>','Dein Fortschritt im Fragenkatalog')}</div><div class="session-grid"><section class="hero"><div><div class="eyebrow">Prüfungsmodus</div><h2>Bereit für die nächste Herausforderung?</h2><p>40 zufällige Fragen aus allen Themen. Teste dein Wissen und erhalte dein Ergebnis am Ende.</p><div class="badge">40 FRAGEN &nbsp; / &nbsp; ZUFÄLLIGE REIHENFOLGE</div><br><button class="primary" id="start">Prüfung starten &nbsp; ↗</button></div><div class="hero-graphic"><strong>40</strong><span>FRAGEN</span></div></section><section class="coverage"><div class="coverage-head"><h3>Dein Lernfortschritt</h3><span>${pct}%</span></div><div class="bar"><i style="width:${pct}%"></i></div><strong>${seen} von ${bank.length} Fragen bearbeitet</strong><p>${bank.length-seen?`Noch ${bank.length-seen} Fragen warten auf dich. Trainiere weiter, um den gesamten Fragenkatalog zu bearbeiten.`:'Du hast alle Fragen bearbeitet! Trainiere weiter, um dein Wissen zu festigen.'}</p>${state.session?'<button id="resume" style="margin-top:17px">Sitzung fortsetzen →</button>':''}</section></div><section id="themes"><div class="section-head"><div><h2>Ein Thema nach dem anderen.</h2><p>Wähle ein Thema und arbeite gezielt an deinen Kenntnissen.</p></div><small>${topics().length} Themen verfügbar</small></div><div class="topics">${topics().map((t,i)=>{let qs=bank.filter(q=>q.thema===t),n=new Set(a.filter(x=>x.theme===t).map(x=>x.qid)).size;return `<article class="topic"><div class="topic-top"><span class="icon">${['{ }','⌘','!','▤','↗','◇','▦','◫','/ /','⇄'][i]}</span><small>${qs.length} Fragen</small></div><h3>${esc(topicLabel(t))}</h3><div class="topic-bottom"><span>${n} / ${qs.length} bearbeitet</span><button data-topic="${i}">Trainieren &nbsp; ↗</button></div></article>`;}).join('')}</div></section><section><div class="section-head"><div><h2>Dein Fortschritt nach Thema.</h2><p>Wiederholte Antworten zählen als neue Versuche.</p></div><button class="reset" id="reset">↺ &nbsp; Statistik zurücksetzen</button></div><div class="table-wrap"><table><thead><tr><th>Thema</th><th>Antworten</th><th>Richtig</th><th>Fehler</th><th>Trefferquote</th></tr></thead><tbody>${topics().map(t=>{const x=a.filter(a=>a.theme===t),c=x.filter(a=>a.correct).length;return `<tr><td>${esc(topicLabel(t))}</td><td>${x.length}</td><td>${c}</td><td class="error-num">${x.length-c}</td><td>${x.length?Math.round(c/x.length*100)+'%':'—'}</td></tr>`;}).join('')}</tbody></table></div></section>`;
document.querySelector('#start').onclick=()=>start(null);document.querySelector('#resume')?.addEventListener('click',quiz);document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>start(topics()[+b.dataset.topic]));document.querySelector('#reset').onclick=()=>document.querySelector('#reset-dialog').showModal();}
function start(theme){if(state.session&&!confirm('Es läuft bereits eine Sitzung. Möchtest du sie ersetzen? Bereits bestätigte Antworten bleiben in der Statistik erhalten.'))return;const pool=bank.filter(q=>!theme||q.thema===theme);let ids=shuffle(pool).slice(0,40).map(q=>q.id);if(ids.length>1&&ids.join()===state.last.join())[ids[0],ids[1]]=[ids[1],ids[0]];state.last=ids;state.session={ids,theme,index:0,answers:{},drafts:{},orders:Object.fromEntries(ids.map(id=>[id,shuffle(bank.find(q=>q.id===id).antworten.map(a=>a.id))])),started:Date.now()};save();quiz();window.scrollTo(0,0);}
function quiz(){const s=state.session;if(!s)return home();const q=bank.find(q=>q.id===s.ids[s.index]),answered=s.answers[q.id],n=Object.keys(s.answers).length,training=!!s.theme;
app.innerHTML=`<div class="quiz">${notice()}<div class="quiz-top"><button id="back-home">← Übersicht</button><span class="badge">${training?'Thementraining':'Prüfungssimulation'} · ${n}/${s.ids.length} bestätigt</span></div><div class="bar"><i style="width:${n/s.ids.length*100}%"></i></div><div class="question-card"><div class="eyebrow">Frage ${s.index+1} von ${s.ids.length}</div><p style="font-size:12px;margin:12px 0">${esc(topicLabel(q.thema))}</p><h1 lang="de">${esc(q.frage)}</h1><div role="group" aria-label="Antworten">${s.orders[q.id].map((id,i)=>{let a=q.antworten.find(a=>a.id===id),sel=s.drafts[q.id]===id;return `<button lang="de" class="answer ${sel?'selected':''} ${answered&&training?(a.correct?'right':answered.answerId===id?'incorrect':''):''}" data-answer="${id}" aria-pressed="${sel}" ${answered?'disabled':''}><b>${String.fromCharCode(65+i)}</b><span>${esc(a.frage)}</span></button>`;}).join('')}</div>${answered?(training?`<div class="feedback ${answered.correct?'':'bad'}" role="status">${answered.correct?'✓ Richtig beantwortet!':'Die Antwort ist leider falsch.'}${!answered.correct?'<br>Richtige Antwort: '+esc(q.antworten.find(a=>a.correct).frage):''}</div>`:'<div class="feedback" role="status">Antwort gespeichert. Die Auswertung folgt am Ende.</div>'):''}<div class="actions"><button id="prev" ${s.index===0?'disabled':''}>← Zurück</button>${!answered?`<button class="dark" id="confirm" ${s.drafts[q.id]===undefined?'disabled':''}>Antwort bestätigen</button>`:`<button class="dark" id="next">${s.index===s.ids.length-1?'Zur Auswertung':'Weiter →'}</button>`}</div></div><div class="navigator" aria-label="Fragennavigation">${s.ids.map((id,i)=>`<button data-index="${i}" class="${s.answers[id]?'done':''} ${i===s.index?'current':''}" aria-label="Frage ${i+1}${s.answers[id]?', Antwort bestätigt':''}">${i+1}</button>`).join('')}</div><div class="actions"><button id="finish">${n===s.ids.length?'Sitzung abschließen':'Beenden und auswerten'}</button></div><p style="font-size:11px;margin-top:20px">Bestätigte Antworten sind endgültig und aktualisieren sofort die Statistik. Unbeantwortete Fragen zählen nicht als Fehler.</p></div>`;
document.querySelector('#back-home').onclick=home;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{s.drafts[q.id]=+b.dataset.answer;save();quiz();});document.querySelector('#confirm')?.addEventListener('click',()=>{if(s.answers[q.id]||s.drafts[q.id]===undefined)return;const id=s.drafts[q.id],correct=q.antworten.find(a=>a.id===id).correct;s.answers[q.id]={answerId:id,correct};state.attempts.push({qid:q.id,theme:q.thema,correct,at:Date.now()});save();quiz();});document.querySelector('#prev').onclick=()=>go(s.index-1);document.querySelector('#next')?.addEventListener('click',()=>s.index===s.ids.length-1?finish():go(s.index+1));document.querySelectorAll('[data-index]').forEach(b=>b.onclick=()=>go(+b.dataset.index));document.querySelector('#finish').onclick=finish;}
function go(i){state.session.index=i;save();quiz();}
function finish(){const s=state.session,n=Object.keys(s.answers).length;if(n<s.ids.length&&!confirm(`Du hast ${n} von ${s.ids.length} Antworten bestätigt. Möchtest du die Sitzung beenden? Die ${s.ids.length-n} unbeantworteten Fragen werden nicht in der Statistik gewertet.`))return;const c=Object.values(s.answers).filter(a=>a.correct).length;const snapshot=structuredClone(s);state.session=null;save();app.innerHTML=`<div class="quiz"><div class="result"><div class="eyebrow">Sitzung abgeschlossen</div><h1>${n?Math.round(c/n*100):0}%</h1><h2>Wieder einen Schritt weiter.</h2><p>${c} richtige von ${n} bestätigten Antworten · ${s.ids.length-n} unbeantwortet</p><div class="stats" style="grid-template-columns:repeat(3,1fr)">${stat('Richtig',c,'Bestätigte Antworten','correct')}${stat('Falsch',n-c,'Zum Wiederholen','wrong')}${stat('Unbeantwortet',s.ids.length-n,'Nicht in der Statistik gewertet')}</div><button class="dark" id="again">Neue Sitzung ↗</button> <button id="dashboard">Zurück zur Übersicht</button></div><h2>Deine Antworten im Rückblick</h2>${snapshot.ids.map((id,i)=>{const q=bank.find(q=>q.id===id),a=snapshot.answers[id];return `<article class="review"><div class="eyebrow">${i+1} · ${a?(a.correct?'✓ Richtig':'✕ Falsch'):'Unbeantwortet'}</div><h3 lang="de" style="margin-top:12px">${esc(q.frage)}</h3>${a?'<p>Deine Antwort: '+esc(q.antworten.find(x=>x.id===a.answerId).frage)+'</p>':''}<p style="color:#32764f">Richtige Antwort: <span lang="de">${esc(q.antworten.find(x=>x.correct).frage)}</span></p></article>`;}).join('')}</div>`;document.querySelector('#dashboard').onclick=home;document.querySelector('#again').onclick=()=>start(snapshot.theme);window.scrollTo(0,0);}
document.querySelector('#home-link').onclick=e=>{e.preventDefault();home();};document.querySelector('.brand').onclick=e=>{e.preventDefault();home();};document.querySelector('nav a:last-child').onclick=e=>{e.preventDefault();home();document.querySelector('#themes').scrollIntoView({behavior:'smooth'});};document.querySelector('#cancel-reset').onclick=()=>document.querySelector('#reset-dialog').close();document.querySelector('#confirm-reset').onclick=()=>{state={attempts:[],session:null,last:[]};save();document.querySelector('#reset-dialog').close();home();};
try{const res=await fetch('fragen.json');if(!res.ok)throw Error('JSON nicht verfügbar');bank=await res.json();if(!Array.isArray(bank)||!bank.length||bank.some(q=>!q.thema||!Array.isArray(q.antworten)||q.antworten.filter(a=>a.correct).length!==1))throw Error('Ungültiges Fragenformat');if(state.session&&!state.session.ids.every(id=>bank.some(q=>q.id===id)))state.session=null;home();}catch(e){app.innerHTML='<div class="empty"><h1>Fragen konnten nicht geladen werden</h1><p>Prüfe deine Verbindung und lade die Seite erneut.</p><button onclick="location.reload()">Erneut versuchen</button></div>';console.error(e);}
